(1, 1, 1, 'using System;\n\nclass Program\n{\n    static void Main(string[] args)\n    {\n        Console.WriteLine(\"¡Hola, mundo!\");\n    }\n}', '¡Hola, mundo!', 'Ejemplo de un programa muy simple que imprime un mensaje en la consola.'),
(2, 1, 2, 'using System;\n\nclass Program\n{\n    static void Main(string[] args)\n    {\n        Console.WriteLine(\"¡Hola, mundo!\")   // Falta el punto y coma\n    }\n}', 'error CS1002: ; expected', 'Mismo programa pero con un error de sintaxis: falta el punto y coma al final de la línea.');
